import {restrictionActive} from './restrictions.js?v=20261010-member-fixes';
const previewResponses=new Map();
export const canRespond=(actor,canRead)=>Boolean(actor&&actor.user_metadata?.status==='approved'&&!restrictionActive(actor.user_metadata)&&canRead);
export function formatDelay(minutes){return [Math.floor(minutes/60)?`${Math.floor(minutes/60)}시간`:'',minutes%60?`${minutes%60}분`:''].filter(Boolean).join(' ');}
export function responseMessage(response,minutes){return response==='attend'?'참석합니다.':response==='decline'?'아쉽지만 이번에는 불참합니다. 마음만은 함께할게요!':`참석합니다! 그런데 ${formatDelay(minutes)}쯤 늦을 것 같아요.. ㅠ.ㅠ 조금만 기다려 주세요!`;}
export function previewRecruitmentComments(id){return [...(previewResponses.get(id)?.values()||[])].map(item=>({...item.member,body:responseMessage(item.response,item.delay_minutes),created_at:item.created_at}));}
export function updateRecruitmentMember(member){for(const answers of previewResponses.values())for(const answer of answers.values())if(answer.member.id===member.id)answer.member={...answer.member,...member};}
export function recruitmentPanel(){return `<section class="recruitment-panel" aria-labelledby="recruitment-title"><div><h2 id="recruitment-title">참석 여부</h2><p id="recruitment-counts" role="status">참석 0명 · 늦참 0명 · 불참 0명</p></div><div class="recruitment-buttons"><button class="secondary" type="button" data-response="attend" aria-pressed="false">참석</button><button class="secondary" type="button" data-response="late" aria-pressed="false">늦참</button><button class="secondary" type="button" data-response="decline" aria-pressed="false">불참</button></div><form class="recruitment-late-form" id="late-response-form" hidden><h3>얼마나 늦을 것 같으세요?</h3><fieldset data-late-fields><div class="late-time-fields"><label>시간<select name="hours" aria-label="늦는 시간">${Array.from({length:24},(_,hour)=>`<option value="${hour}">${hour}시간</option>`).join('')}</select></label><label>분<select name="minutes" aria-label="늦는 분">${[0,10,20,30,40,50].map(minute=>`<option value="${minute}" ${minute===30?'selected':''}>${minute}분</option>`).join('')}</select></label></div><div class="late-time-actions"><button class="secondary" type="button" data-cancel-late>취소</button><button class="primary" type="submit">확인</button></div></fieldset></form><p class="form-note" id="recruitment-note">선택하면 본인 이름으로 댓글이 작성됩니다. 변경하면 기존 댓글이 수정됩니다.</p><p class="form-error" id="recruitment-error" role="alert"></p></section>`;}
export async function bindRecruitment(main,{post,actor,db,canRead,isCurrent,onAuth,onChanged}){
 const root=main.querySelector('.recruitment-panel');if(!root)return;
 const alive=()=>isCurrent()&&main.contains(root),eligible=canRespond(actor,canRead),form=root.querySelector('#late-response-form'),error=root.querySelector('#recruitment-error');
 let busy=false,state={attend:0,late:0,decline:0,mine:null,mine_delay_minutes:null};
 const localState=()=>{const answers=previewResponses.get(post.id)||new Map(),all=[...answers.values()],mine=answers.get(actor?.id);return{attend:all.filter(a=>a.response==='attend').length,late:all.filter(a=>a.response==='late').length,decline:all.filter(a=>a.response==='decline').length,mine:mine?.response||null,mine_delay_minutes:mine?.delay_minutes??null};};
 function draw(){root.querySelector('#recruitment-counts').textContent=`참석 ${state.attend||0}명 · 늦참 ${state.late||0}명 · 불참 ${state.decline||0}명`;for(const button of root.querySelectorAll('[data-response]')){button.setAttribute('aria-pressed',String(state.mine===button.dataset.response));button.disabled=busy||Boolean(actor&&!eligible);}form.querySelector('fieldset').disabled=busy||!eligible;if(!actor)root.querySelector('#recruitment-note').textContent='로그인 후 참석 여부를 남길 수 있습니다.';else if(!eligible)root.querySelector('#recruitment-note').textContent='승인된 회원만 참석 여부를 남길 수 있습니다.';}
 try{if(db){const{data,error:failure}=await db.rpc('get_recruitment_response',{p_post:post.id});if(failure)throw failure;if(!alive())return;state=data;}else state=localState();draw();}catch{if(alive())error.textContent='참석 현황을 불러오지 못했어요. 새로고침해 주세요.';return;}
 async function save(response,minutes=null){if(busy||!alive()||!eligible)return;busy=true;error.textContent='';draw();try{if(db){const{data,error:failure}=await db.rpc('set_recruitment_response',{p_post:post.id,p_response:response,p_delay_minutes:minutes});if(failure)throw failure;if(!alive())return;state=data;}else{if(!previewResponses.has(post.id))previewResponses.set(post.id,new Map());const answers=previewResponses.get(post.id),previous=answers.get(actor.id);answers.set(actor.id,{response,delay_minutes:minutes,member:{id:actor.id,...actor.user_metadata},created_at:previous?.created_at||new Date().toISOString()});state=localState();}if(alive()){form.hidden=true;await onChanged();}}catch{if(alive())error.textContent='저장하지 못했어요. 로그인 상태와 게시판 권한을 확인해 주세요.';}finally{busy=false;if(alive())draw();}}
 root.addEventListener('click',event=>{const button=event.target.closest('[data-response]');if(!button||busy)return;if(!actor){onAuth();return;}if(!eligible)return;error.textContent='';if(button.dataset.response==='late'){const minutes=state.mine==='late'?state.mine_delay_minutes:30;form.elements.hours.value=String(Math.floor((minutes??30)/60));form.elements.minutes.value=String((minutes??30)%60);form.hidden=false;form.elements.hours.focus();}else{form.hidden=true;void save(button.dataset.response);}});
 form.querySelector('[data-cancel-late]').onclick=()=>{form.hidden=true;error.textContent='';root.querySelector('[data-response="late"]').focus();};
 form.onsubmit=event=>{event.preventDefault();const hours=Number(form.elements.hours.value),minutes=Number(form.elements.minutes.value),total=hours*60+minutes;if(!Number.isInteger(hours)||hours<0||hours>23||![0,10,20,30,40,50].includes(minutes)||total<10){error.textContent='늦는 시간을 10분 이상 선택해 주세요.';return;}void save('late',total);};
}
